"""Form 5 French (O Level 0545): practice sets for Compréhension Écrite et Traduction, Expression Écrite and Examination.

Draft content. Exam facts are those of the Board's 2023 report only (Paper 1 = 50 multiple-choice questions, 40% of the
examination, marked electronically; Paper 2 = Translation and Essay). The times of 'Paper 1 mock exam A' (90 minutes) and
'Paper 2 practice paper A' (150 minutes) are KKEVO practice settings. Translation and essay writing cannot be marked
automatically, so Paper 2 practice paper A tests choices, error spotting, planning and word order.
All passages, sentences and model answers are KKEVO originals.
"""

from .dsl import *  # noqa: F403

COURSE = ("french", "form-5")

M_READ = "Compréhension Écrite et Traduction"
M_WRITE = "Expression Écrite"
M_ESSAY = "Expression Écrite"
M_EXAM = "Examination"

_N = [0]


def _reset():
    _N[0] = 0


def Q(prompt, right, wrong, concept, skill, hint, expl, fb=""):
    """Multiple-choice question; the correct option's position cycles through A-D automatically.

    `wrong` is a list of three (text, why) pairs; `expl` is a short solution text.
    """
    pos = _N[0] % 4
    _N[0] += 1
    choices = [C(t, why=w) for t, w in wrong]
    choices.insert(pos, C(right, correct=True))
    return MC(prompt, choices, steps=[S("Solution", text=expl)], concept=concept, skill=skill, hint=hint, feedback=fb or expl)


